import{idb}from"../utils/idb.js";import{escapeHtml,truncate,showToast,debounce,timeAgo,formatDateShort}from"../utils/helpers.js";export async function renderFavorites(){document.getElementById("page-container").innerHTML='\n    <div class="page">\n      <div class="container">\n        <div class="page-header">\n          <h1 class="page-title">Favorit Saya</h1>\n          <p class="page-subtitle">Koleksi cerita yang Anda simpan di perangkat ini</p>\n        </div>\n\n        <div class="toolbar">\n          <input\n            type="search"\n            id="favSearch"\n            class="search-box"\n            placeholder="Cari di favorit..."\n            aria-label="Cari cerita favorit"\n          />\n          <select id="favSort" class="sort-box" aria-label="Urutkan favorit">\n            <option value="savedAt_desc">Terbaru disimpan</option>\n            <option value="savedAt_asc">Terlama disimpan</option>\n            <option value="name_asc">Nama A–Z</option>\n            <option value="name_desc">Nama Z–A</option>\n            <option value="createdAt_desc">Dibuat terbaru</option>\n            <option value="createdAt_asc">Dibuat terlama</option>\n          </select>\n          <button id="clearAllBtn" class="btn btn-danger btn-sm" aria-label="Hapus semua favorit">🗑 Hapus Semua</button>\n        </div>\n\n        <p id="favCount" class="text-sm text-muted font-mono" style="margin-bottom:1rem" aria-live="polite"></p>\n\n        <div id="favGrid" class="stories-grid" aria-live="polite" aria-label="Daftar cerita favorit"></div>\n      </div>\n    </div>\n  ',await loadFavorites(),initControls()}let currentQuery="",currentSort="savedAt_desc";async function loadFavorites(){const a=document.getElementById("favGrid"),t=document.getElementById("favCount");if(a)try{let e=await idb.getAllFavorites();if(currentQuery){const a=currentQuery.toLowerCase();e=e.filter(t=>t.name?.toLowerCase().includes(a)||t.description?.toLowerCase().includes(a))}const[n,i]=currentSort.split("_");if(e.sort((a,t)=>{const e=(a[n]||"").toLowerCase(),r=(t[n]||"").toLowerCase();return"asc"===i?e>r?1:-1:e<r?1:-1}),t){const a=(await idb.getAllFavorites()).length;t.textContent=currentQuery?`Menampilkan ${e.length} dari ${a} favorit`:`${a} cerita favorit`}if(!e.length)return void(a.innerHTML=`\n        <div class="empty-state">\n          <h3>${currentQuery?"Tidak ditemukan":"Belum ada favorit"}</h3>\n          <p>${currentQuery?"Coba kata kunci lain":"Tekan tombol pada cerita untuk menyimpannya"}</p>\n          ${currentQuery?"":'<a href="#/explore" class="btn btn-primary" style="margin-top:1rem">Jelajahi Cerita</a>'}\n        </div>\n      `);a.innerHTML=e.map(a=>favCard(a)).join(""),bindEvents(a)}catch(t){a.innerHTML=`<div class="empty-state"><h3>Gagal memuat</h3><p>${escapeHtml(t.message)}</p></div>`}}function favCard(a){const t=a.photoUrl?`<img class="card-img" src="${escapeHtml(a.photoUrl)}" alt="Foto cerita ${escapeHtml(a.name)}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">`:"",e=`<div class="card-img-placeholder" ${a.photoUrl?'style="display:none"':""} aria-hidden="true"><i class="fas fa-image"></i></div>`;return`\n    <article class="card" data-id="${escapeHtml(a.id)}">\n      <a href="#/stories/${escapeHtml(a.id)}" aria-label="Baca cerita oleh ${escapeHtml(a.name)}">\n        ${t}${e}\n      </a>\n      <div class="card-body">\n        <h3 class="card-title">\n          <a href="#/stories/${escapeHtml(a.id)}">${escapeHtml(a.name)}'s Story</a>\n        </h3>\n        <p class="card-text">${escapeHtml(truncate(a.description,110))}</p>\n        <div class="card-meta">\n          <span title="${escapeHtml(a.createdAt)}">${timeAgo(a.createdAt)}</span>\n          <span style="color:var(--accent-light)">❤️${formatDateShort(a.savedAt)}</span>\n        </div>\n        <div class="card-actions">\n          <a href="#/stories/${escapeHtml(a.id)}" class="btn btn-secondary btn-sm">Baca →</a>\n          <button\n            class="btn btn-danger btn-sm rm-fav-btn"\n            data-id="${escapeHtml(a.id)}"\n            aria-label="Hapus ${escapeHtml(a.name)} dari favorit"\n          >🗑 Hapus</button>\n        </div>\n      </div>\n    </article>\n  `}function bindEvents(a){a.querySelectorAll(".rm-fav-btn").forEach(t=>{t.addEventListener("click",async e=>{e.preventDefault();const n=t.dataset.id,i=a.querySelector(`[data-id="${n}"]`);i&&(i.style.transition="all .25s ease",i.style.opacity="0",i.style.transform="scale(.9)",await new Promise(a=>setTimeout(a,250)),i.remove()),await idb.removeFavorite(n),showToast("Dihapus dari favorit","info");const r=await idb.getAllFavorites(),s=document.getElementById("favCount");s&&(s.textContent=`${r.length} cerita favorit`),r.length||await loadFavorites()})})}function initControls(){const a=document.getElementById("favSearch"),t=document.getElementById("favSort"),e=document.getElementById("clearAllBtn");a?.addEventListener("input",debounce(a=>{currentQuery=a.target.value.trim(),loadFavorites()},300)),t?.addEventListener("change",a=>{currentSort=a.target.value,loadFavorites()}),e?.addEventListener("click",async()=>{const a=await idb.getAllFavorites();if(a.length){if(confirm(`Hapus semua ${a.length} favorit? Tindakan ini tidak bisa dibatalkan.`)){for(const t of a)await idb.removeFavorite(t.id);showToast(`${a.length} favorit dihapus`,"success"),await loadFavorites()}}else showToast("Tidak ada favorit","info")})}